Lemma inv_scratch Mi Mj mdi cri ki j lo hi : inv Mi mdi cri ki j -> sp - 16384 <= lo -> hi <= sp - 32 ->
  mem_grows Mi Mj -> (forall i, 0 <= i < 2 ^ 64 -> ~ (lo <= i < hi) -> Mj (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
